INSERT INTO categories (name, slug) VALUES ('Notebooks & Macbooks', 'notebooks') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;

-- 2. Asegurar Marcas
INSERT INTO brands (name, slug) VALUES 
  ('Apple', 'apple'), ('Samsung', 'samsung'), ('Lenovo', 'lenovo'), 
  ('HP', 'hp'), ('Dell', 'dell'), ('Acer', 'acer'), ('Asus', 'asus'), 
  ('MSI', 'msi'), ('Acer', 'acer') ON CONFLICT (slug) DO NOTHING;

CREATE OR REPLACE FUNCTION _zentek_insert(p_name text, p_slug text, p_cat_slug text, p_brand_slug text, p_price_usd numeric) RETURNS void AS $$
DECLARE v_cat_id uuid; v_brand_id uuid; v_prod_id uuid; v_var_id uuid;
BEGIN
  SELECT id INTO v_cat_id FROM categories WHERE slug = p_cat_slug;
  SELECT id INTO v_brand_id FROM brands WHERE slug = p_brand_slug;
  INSERT INTO products (name, slug, category_id, brand_id, condition, active) VALUES (p_name, p_slug, v_cat_id, v_brand_id, 'new', true) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, updated_at = now() RETURNING id INTO v_prod_id;
  INSERT INTO product_variants (product_id, sku, active) VALUES (v_prod_id, p_slug || '-v1', true) ON CONFLICT (sku) DO NOTHING RETURNING id INTO v_var_id;
  IF v_var_id IS NULL THEN SELECT id INTO v_var_id FROM product_variants WHERE sku = p_slug || '-v1'; END IF;
  INSERT INTO prices (variant_id, currency, amount) VALUES (v_var_id, 'USD', p_price_usd) ON CONFLICT (variant_id, currency) DO UPDATE SET amount = EXCLUDED.amount, updated_at = now();
END; $$ LANGUAGE plpgsql;

